select au.id as authorId,au.nickname as authorName, ac.inCost from author_user au
left join(
    select target_id,count(*) as h5Fans from member_user_follow
    where status = 0 and target_type = 1 and user_status = 1

        and date_format(create_time, '%Y-%m-%d' ) between #{reqVO.userStartDate} and #{reqVO.userEndDate}

    group by target_id
)ma on ma.target_id = au.id
left join(
    select ifnull(sum(in_cost),0) as inCost,author_id from author_cost
    where status = 0

            and `date` between #{reqVO.costStartDate} and #{reqVO.costEndDate}


    group by author_id
)ac on ac.author_id = au.id
where au.author_source = 1

    and au.id IN

        #{id}



    and au.id in

        #{item}

